# 새 외전 출신의 사건에 덧붙이는 거친 길. 정도의 길만 넓지 않게 사도와 마도의 선택지를 보탠다
from dsl import *
def add(event, choice): (STORY.get(event) or RANDOM[event])["choices"].append(choice)

# 소림
add("서장_외전소림",C("닫힌 문을 걷어차고 돌아선다",O("문이 울렸다. 안에서 아무도 답하지 않았다. 열두 권은 찾겠다. 다만 문 안의 사람들을 위해서는 아니다.",alignment=AL(m=20),stats={"external":1})))
add("외전소림_2",C("경매장의 은자 궤까지 털어 나온다",O("사본과 은자 궤를 함께 들고 나왔다. 경매꾼은 벽에 붙어 떨었다. 소림의 속가가 사도련의 경매장을 털었다는 소문이 낙양에 돌았다.",battle="절정고수",foe="사도련 경매장지기 쌍칼 구문",foe_line="\"소림의 곤이 은자 궤를 노리는가.\"",alignment=AL(m=40,s=20),silver=80,stats={"martial":3},flags=["소림_경매","소림_권수","소림_사도련원한"])))
add("외전소림_4",C("척살조의 우두머리를 꺾어 들판 어귀에 본보기로 세워 둔다",O("쓰러진 우두머리를 곤에 묶어 들판 어귀에 세웠다. 척살조는 그 들판을 다시 지나지 않았다. 장정들이 나를 멀리서 보았다.",battle="마교척살조",foe="천마신교 적수대 셋째 조",foe_line="\"소림의 곤이 이렇게 거칠었던가.\"",lose_flags=["소림_들"],alignment=AL(m=50),stats={"external":5,"martial":4},fame=20,flags=["소림_들","소림_본보기"])))
add("소림_빈암자",C("비구니에게서 사본을 빼앗듯 거둔다",O("그녀는 저항하지 않았다. 염불이 끊겼다. 사본은 내 품에 있다. 주먹밥은 받지 못했다.",alignment=AL(m=40),stats={"martial":3},flags=["소림_권수"])))
add("소림_산적의곤",C("두목의 곤을 빼앗아 그 곤으로 두 다리를 부순다",O("두목이 다시는 곤을 쥐지 못할 것이다. 산채의 졸개들이 무릎을 꿇었다. 사본은 피에 젖었다.",battle="녹림채주",foe="곤을 든 산채 두목 철봉 마구",foe_line="\"장터에서 산 곤도 곤이다.\"",alignment=AL(m=40),stats={"external":5},flags=["소림_권수"])))
# 무당
add("서장_외전무당",C("두 사형 모두 무당을 망칠 자라 여기고 돌문 앞에 검을 꽂는다",O("검이 돌바닥에 박혔다. 누구든 문 앞에 오면 이 검부터 넘어야 한다. 두 사형 누구에게도 고개를 숙이지 않았다.",alignment=AL(m=20),stats={"martial":1})))
add("외전무당_4",C("성을 버리고 신교의 진에 숨어들어 장수를 벤다",O("성벽이 아니라 진의 한가운데로 갔다. 장수의 막사에 불을 질렀다. 성은 버텼다. 진무의 제자 다섯이 그 밤 성벽에서 죽었다. 내가 성벽에 있었다면 몇이 살았을지 모른다.",battle="마교척살조",foe="균주를 에운 신교 진의 장수 호위",foe_line="\"무당의 검이 진 한가운데로 왔구나.\"",lose_flags=["무당_균주"],alignment=AL(m=50),stats={"martial":5,"external":3},fame=20,flags=["무당_균주","무당_진습"])))
add("무당_향객",C("향객의 은자를 빼앗고 산 아래로 쫓아낸다",O("향객이 계단을 굴러 내려갔다. 맹이 무당을 사려 한다면 값부터 받아야 한다. 은자는 돌문 앞에 두었다. 그 돈을 어디에 쓸지는 아직 정하지 않았다.",alignment=AL(m=30,s=10),silver=40)))
add("무당_하산제자",C("맹의 장부를 쓴 어른을 찾아가 칼을 겨눈다",O("어른은 뒷줄에서 장부를 쓰고 있었다. 검끝이 붓 위에 놓였다. 그날 밤 무당 제자들의 이름이 앞줄에서 지워졌다. 맹에 내 이름이 적혔을 것이다.",alignment=AL(m=40),stats={"martial":4},flags=["무당_장부"])))
# 아미
add("외전아미_2",C("적수대 둘을 베고 그 붉은 소매를 고을 어귀에 걸어 둔다",O("붉은 소매 둘이 고을 어귀의 장대에 걸렸다. 홍란이 그것을 보고 얼굴을 돌렸다. 적수대는 그 고을로 다시 오지 않았다.",battle="마교척살조",foe="신교 적수대 둘째 조",foe_line="\"아미의 속가가 신교의 일에 끼어드는가.\"",lose_flags=["아미_쫓김"],alignment=AL(m=50),stats={"external":5,"martial":3},flags=["아미_쫓김","아미_장대"])))
add("외전아미_3",C("장부를 불살라 지난 일을 재로 만들자고 한다",O("홍란이 장부를 끌어안았다. \"재로 만들면 그 아이들도 재가 돼요.\" 장부는 타지 않았다. 그날 밤 홍란은 장부를 베고 잤다.",alignment=AL(m=30),stats={"mind":4},flags=["아미_장부"])))
add("외전아미_4",C("수레 길 역참의 심판자를 먼저 쳐서 길을 연다",O("역참의 문을 걷어찼다. 연못을 지키던 신교의 형리가 칼을 뽑기도 전에 장이 닿았다. 홍란이 역참 안을 보았다. 아이들의 신발이 쌓여 있었다.",battle="혈교수련자",foe="연못 길 역참의 형리 장오",foe_line="\"수레 길에 사람이 오다니. 백 년 만이다.\"",lose_flags=["아미_수레길"],alignment=AL(m=40),stats={"external":4,"internal":3},flags=["아미_수레길","아미_역참"])))
add("아미_밤의발소리",C("넷 가운데 하나만 살려 보내 신교에 겁을 전하게 한다",O("셋을 눕히고 넷째의 손목을 꺾었다. \"가서 전해라. 이 여인을 쫓는 자는 이렇게 된다고.\" 그 뒤로 지붕의 발소리가 한동안 들리지 않았다.",battle="마교척살조",foe="신교 적수대 넷째 조",foe_line="\"배신자는 자고 있구나.\"",alignment=AL(m=40),stats={"martial":4,"external":2})))
# 공동
add("서장_외전공동",C("맹이 남기고 간 깃발을 찾아내 깃대 아래에서 불사른다",O("맹의 깃발이 재가 되었다. 보 사람들이 그 불을 둘러섰다. 누구도 말리지 않았다. 버린 자의 깃발은 이 보에 걸릴 자리가 없다.",alignment=AL(m=20),stats={"external":1},flags=["공동_깃발태움"])))
add("외전공동_3",C("마적의 두목을 꺾어 모래 언덕에 묻고 그 패거리를 보의 짐꾼으로 부린다",O("두목을 묻은 언덕 아래에서 마적들이 흙벽을 쌓았다. 대상들은 보를 두려워하며 값을 치렀다.",battle="녹림채주",foe="검은 두건 마적의 두목 사묵",foe_line="\"이 길은 동쪽에 바치는 길이다.\"",lose_flags=["공동_대상"],alignment=AL(m=40,s=10),silver=60,stats={"martial":4},flags=["공동_대상","공동_마적부림"])))
add("공동_철혈대",C("천호의 화살을 받고 철혈대의 군량 수레도 몰래 털어 온다",O("관도의 수레 하나가 사하보로 왔다. 천호는 끝내 알아차리지 못했다. 그 겨울 보 사람들은 배불리 먹었다.",alignment=AL(m=30,s=20),silver=40,stats={"martial":2})))
add("공동_무너진벽",C("무너진 자리로 들어오는 자는 모두 벤다는 말뚝을 박는다",O("말뚝 위에 마적의 칼 하나를 꽂았다. 그 밤 무너진 자리를 넘은 자는 없었다. 보 사람들도 그 말뚝을 피해 다녔다.",alignment=AL(m=30),stats={"martial":3})))
# 모용
add("서장_외전모용",C("직계들 앞에서 사당의 촛대를 꺾고 나선다",O("촛대가 바닥에 굴렀다. 직계들이 칼자루를 잡았다. 가주는 그들을 손으로 막았다. \"방계의 화가 백 년 묵었구나. 가거라.\"",alignment=AL(m=20),stats={"external":1})))
add("외전모용_2",C("채삼관의 관병을 베고 장부를 불태운다",O("관병의 장부가 불탔다. 삼꾼들의 빚도 함께 탔다. 채삼관은 그 산을 사흘 동안 비웠다. 늙은 삼꾼이 무덤 자리를 일러 주며 떨었다.",battle="금의위밀정",foe="채삼관의 관병 우두머리 장패",foe_line="\"삼밭에서 창을 휘두르는 자는 삼 도둑이다.\"",lose_flags=["모용_무덤"],alignment=AL(m=40),stats={"external":4,"martial":3},flags=["모용_무덤","모용_채삼관"])))
add("외전모용_3",C("나루의 붉은 소매에게 창의 행방을 팔고 값을 받는다",O("붉은 소매가 은자를 던지며 웃었다. \"모용의 피가 모용의 창을 판다.\" 그들보다 먼저 가면 그만이다.",alignment=AL(m=30,s=20),silver=70,stats={"mind":2},flags=["모용_신교거래"])))
add("모용_채삼관",C("관인의 목에 창끝을 대고 표를 공짜로 받는다",O("관인이 떨며 표를 썼다. 삼꾼들 몫까지 썼다. 관문을 지나며 뒤를 보니 관인이 바닥에 주저앉아 있었다.",alignment=AL(m=30),stats={"martial":3},flags=["모용_삼꾼"])))
# 제갈
add("서장_외전제갈",C("스승을 쫓기 전에 스승의 공방을 불태운다",O("남은 그림이 있다면 함께 타야 한다. 불길 속에서 목우의 다리 그림이 오그라들었다. 가주가 그것을 보고도 말리지 않았다.",alignment=AL(m=20),stats={"martial":1})))
add("외전제갈_3",C("조운관을 겁박해 기관선을 통째로 가라앉힌다",O("배가 운하 한가운데에서 가라앉았다. 곡식도 함께 가라앉았다. 서울의 쌀값이 다시 올랐다. 설계도 넉 장은 강바닥에 있다.",alignment=AL(m=50),stats={"martial":4},flags=["제갈_운하","제갈_장수","제갈_가라앉힘"])))
