add("제갈_군사의편지",C("답장에 맹의 어른들 대신 기관을 믿으라고 적는다",O("제갈청은 그 편지를 맹의 군막에 걸었다. 맹의 어른 몇이 불쾌해했다. 서자가 맹을 깔본다는 말이 돌았다.",alignment=AL(m=20,s=10),stats={"mind":3},flags=["제갈_청"])))
# 사도련
add("외전사도련_3",C("종남의 외당 권사 셋을 베고 산문에 빚 문서를 박아 둔다",O("산문 기둥에 빚 문서가 칼로 박혔다. 종남은 그날 산문을 닫았다. 사도련 장부의 줄은 그대로였다. 곽태가 말했다. \"빚은 못 받았지만 이자는 받았구나.\"",battle="종남검수",foe="종남 외당의 권사들",foe_line="\"빚쟁이의 칼이 산문까지 왔구나.\"",lose_flags=["사도련_종남"],alignment=AL(m=50),stats={"martial":5},flags=["사도련_종남","사도련_산문칼"])))

