add("소림_혈풍죽솥",C("솥을 지키는 승려에게 저잣거리의 자릿세를 받는다",O("승려가 은자를 내밀며 웃었다. \"소림의 속가가 자릿세를 받는구려.\" 솥은 그대로 걸려 있었다.",alignment=AL(s=40),silver=40)))
add("소림_겁화흰사슴",C("사냥꾼들에게서 내단을 빼앗아 내가 삼킨다",O("내단이 단전에서 불처럼 탔다. 사흘을 앓았다. 사슴의 눈이 꿈에 나왔다. 기운은 남았다.",battle="마교척살조",foe="신교의 내단 사냥꾼",foe_line="\"영물 하나에 겁화대 하나다.\"",alignment=AL(m=50),hp_pct=-20,stats={"internal":6,"external":2})))
add("소림_천붕빈자리",C("사자에게 은자를 쥐여 주고 소림의 이름을 의심 명부에서 빼 달라 한다",O("사자가 은자를 받고 웃었다. 그 웃음이 조금 길었다. 소림의 이름은 명부에서 빠졌을 것이다. 다른 이름이 들어갔을 것이다.",alignment=AL(s=30),silver=-30,stats={"mind":2})))
add("외전소림_3",C("사본을 마을에 비싸게 팔아넘긴다",O("촌장이 마을의 곡식을 팔아 값을 치렀다. 사본은 이 마을의 것이 되었다. 장부에는 팔았다고 적었다. 방장께는 무어라 아뢸지 모르겠다.",alignment=AL(s=40),silver=90,flags=["소림_석교","소림_남긴권"])))
add("무당_겁화학",C("학의 날개에 남은 불기운을 내 검에 입혀 본다",O("검이 검게 달아올랐다. 학은 그 사이 숨을 거두었다. 검에서 불기운이 빠지는 데 한 달이 걸렸다.",alignment=AL(m=40),stats={"internal":4,"martial":2})))
add("무당_혈풍행렬",C("행렬에게 죽값을 받고 산 아래 길을 내준다",O("승려가 은자를 내밀었다. 행렬은 무당산 기슭의 다른 길로 돌았다. 송결이 산문 위에서 혀를 찼다.",alignment=AL(s=40),silver=50)))
add("외전무당_3",C("표를 던지는 대가로 장로에게 서고의 열쇠를 청한다",O("장로가 이를 갈며 열쇠를 내밀었다. 표는 그 장로의 뜻대로 던졌다. 서고에서 무당의 옛 검보를 밤새 읽었다.",alignment=AL(s=40),stats={"martial":4},mastery=12,flags=["무당_하산표"])))
add("아미_종루소식",C("답장 대신 적수대의 움직임을 맹에 팔 셈을 한다",O("맹의 지부가 값을 치렀다. 그 은자로 홍란의 새 신발을 샀다. 홍란은 어디서 난 돈인지 묻지 않았다.",alignment=AL(s=40),silver=50)))
add("아미_천붕검사",C("검사관에게 은자를 쥐여 주고 성문을 지난다",O("은자가 손에서 손으로 갔다. 검사관은 홍란의 단전을 짚는 척만 했다. 의심도 값이 있다.",alignment=AL(s=30),silver=-20,stats={"mind":2})))
add("공동_대상의노래",C("낙타몰이의 서쪽 마을 이야기를 듣고 그 마을을 털 셈을 해 본다",O("스무 날 거리. 중원의 말을 쓰는 마을. 주먹을 잘 쓴다니 털기는 어렵겠다. 셈만 하고 그만두었다. 셈한 것만으로도 마음이 무거웠다.",alignment=AL(m=30,s=10),stats={"mind":3})))
add("모용_겁화흰범",C("사냥꾼들을 꺾고 그들의 내단 상자를 빼앗아 판다",O("상자 속에 내단 둘이 있었다. 장터의 약재상이 은자 궤를 내밀었다. 흰 범은 그사이 산으로 사라졌다.",battle="마교척살조",foe="장백을 넘어온 내단 사냥꾼",foe_line="\"범 한 마리에 겁화대 하나다.\"",alignment=AL(m=30,s=30),silver=100)))
add("외전모용_4",C("본가로 가는 직계들의 길에 거짓 소식을 흘려 시간을 번다",O("직계들은 엉뚱한 관문으로 갔다. 그사이 북쪽으로 떠났다. 본가가 알면 족보는 더 멀어질 것이다.",alignment=AL(s=30,m=20),stats={"mind":4},flags=["모용_산해관","모용_북행"])))
add("제갈_천붕원로",C("원로를 묶어 두고 그 웃음을 사흘 동안 기관으로 재 본다",O("사흘 동안 원로의 단전에 구리관을 댔다. 물이 끓는 때를 적었다. 원로는 그 사이 반쯤 미쳤다. 적은 것은 쓸모가 있었다.",alignment=AL(m=40),stats={"mind":5},flags=["제갈_천붕"])))
add("제갈_겁화풀무",C("풀무를 고쳐 신교에 되판다",O("신교의 화로지기가 은자를 세며 웃었다. \"제갈의 손이 화로를 고치는구나.\" 풀무는 더 잘 돌았다.",alignment=AL(m=30,s=30),silver=90)))
add("외전사도련_2",C("어미와 딸 앞에서 가게에 불을 놓아 하문을 불러낸다",O("연기를 보고 하문이 돌아왔다. 빚은 다 받았다. 가게는 다 탔다. 딸이 나를 끝까지 노려보았다.",alignment=AL(m=50),silver=70,flags=["사도련_하문","사도련_불"])))

READ=[({"flag":"소림_본보기"},"들판 어귀에 세워 둔 척살조 우두머리의 이야기는 그 들판에서 오래 무섭게 전해졌다."),
 ({"flag":"무당_진습"},"신교의 진 한가운데로 갔던 밤의 일을 진무는 오래 묻지 않았다."),
 ({"flag":"무당_장부"},"맹의 장부를 쓰던 어른의 붓 위에 놓였던 검끝을 그 어른은 평생 잊지 못했다."),
 ({"flag":"아미_장대"},"고을 어귀 장대의 붉은 소매 둘을 홍란은 끝내 똑바로 보지 못했다."),
 ({"flag":"아미_역참"},"수레 길 역참에 쌓여 있던 아이들의 신발을 홍란은 하나씩 묻었다."),
 ({"flag":"공동_깃발태움"},"깃대 아래에서 탄 맹의 깃발 재는 사하보의 흙벽에 섞여 들어갔다."),
 ({"flag":"공동_마적부림"},"마적들이 쌓은 흙벽은 보에서 가장 높았다."),
 ({"flag":"모용_신교거래"},"신교에 창의 행방을 판 일은 본가가 끝내 알지 못했다."),
 ({"flag":"제갈_가라앉힘"},"운하 바닥의 기관선은 그 뒤로 몇 해 동안 뱃사람들의 경계 표지가 되었다."),
 ({"flag":"사도련_불"},"불탄 비단 가게의 딸은 몇 해 뒤 추심당 문 앞에 섰다. 손에 칼을 들고."),
 ({"flag":"사도련_산문칼"},"종남 산문 기둥의 칼자국은 사도련 장부보다 오래 남았다.")]
